ACCOUNT_HTML = r'''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>DaemonBlackFx · Cuenta activa</title>
<style>:root{color-scheme:dark;--bg:#050708;--p:#0a0e10;--p2:#10161a;--t:#f5f5f2;--m:#9fa2a5;--l:#5b4514;--g:#00db79;--r:#ff453a;--y:#f5bd36;--b:#d79b19}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--t);font:14px system-ui}.w{max-width:1380px;margin:auto;padding:18px}.brand{display:flex;align-items:center;gap:14px;margin-bottom:16px;padding-bottom:14px;border-bottom:1px solid var(--l)}.brand img{width:54px;height:54px;object-fit:cover;border-radius:10px;border:1px solid #765719}.brand strong{font-size:20px;letter-spacing:.04em}.brand strong span{color:#f4c84f}.top{display:flex;justify-content:space-between;gap:14px;align-items:start;flex-wrap:wrap}.top h1{margin:0}.muted{color:var(--m)}.nav{display:flex;gap:8px}.btn{color:var(--t);background:var(--p2);border:1px solid var(--l);padding:8px 11px;border-radius:8px;text-decoration:none;font-size:12px}.grid{display:grid;grid-template-columns:repeat(12,1fr);gap:12px;margin-top:15px}.c{background:var(--p);border:1px solid var(--l);border-radius:14px;padding:14px;min-width:0;box-shadow:inset 0 1px 0 rgba(255,211,102,.03)}.k{grid-column:span 3}.half{grid-column:span 6}.full{grid-column:1/-1}.lab{color:var(--m);font-size:11px;text-transform:uppercase;letter-spacing:.06em}.val{font-size:25px;font-weight:800;margin-top:5px}.stats{display:grid;grid-template-columns:repeat(6,1fr);gap:8px;margin-top:10px}.s{background:var(--p2);padding:10px;border-radius:9px;min-width:0}.s b{display:block;font-size:19px}.bar{height:14px;background:#192a37;border-radius:99px;overflow:hidden;display:flex;margin:12px 0}.leg{display:flex;gap:12px;flex-wrap:wrap;color:var(--m);font-size:12px}.ranking{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:9px;margin-top:10px}.strategy{padding:11px;background:var(--p2);border:1px solid #263139;border-radius:10px}.strategyHead{display:flex;justify-content:space-between;gap:8px;font-weight:800}.strategyMeta{display:flex;gap:8px;flex-wrap:wrap;color:var(--m);font-size:11px;margin-top:7px}.strategy .profit{font-size:16px}.good{color:var(--g)}.bad{color:var(--r)}.warn{color:var(--y)}.historyHead{display:flex;justify-content:space-between;gap:12px;align-items:end;flex-wrap:wrap}.tbl{overflow-y:auto;overflow-x:hidden;max-height:620px;margin-top:10px;border:1px solid var(--l);border-radius:9px}table{width:100%;max-width:100%;border-collapse:collapse;table-layout:fixed}th,td{padding:10px 8px;border-bottom:1px solid #302914;text-align:left;vertical-align:top;font-size:12px;overflow-wrap:anywhere}th{color:var(--m);font-size:10px;text-transform:uppercase;letter-spacing:.04em;position:sticky;top:0;background:var(--p);z-index:2}th:nth-child(1),td:nth-child(1){width:5%}th:nth-child(2),td:nth-child(2){width:17%}th:nth-child(3),td:nth-child(3){width:13%}th:nth-child(4),td:nth-child(4){width:17%}th:nth-child(5),td:nth-child(5){width:15%}th:nth-child(6),td:nth-child(6){width:13%}th:nth-child(7),td:nth-child(7){width:20%}.tradeMeta{color:var(--m);font-size:11px;margin-top:3px}.auditCard{display:grid;gap:7px;min-width:0;padding:9px;border:1px solid #4a3b18;border-radius:10px;background:linear-gradient(180deg,#111710,#0b0f11);box-shadow:inset 3px 0 0 var(--b)}.auditDecision{color:var(--y);font-weight:850;font-size:11px;line-height:1.3;overflow-wrap:anywhere}.auditMeta{display:flex;gap:5px;flex-wrap:wrap}.auditStat{display:inline-flex;align-items:center;padding:3px 6px;border:1px solid #3d351d;border-radius:6px;background:#151a1c;color:var(--m);font-size:10px}.auditStat b{color:var(--t);margin-left:3px}.auditPattern{font-size:10px;color:var(--m);line-height:1.35}.auditPattern b{color:var(--g)}.auditOpen{display:flex;align-items:center;justify-content:center;margin-top:1px;padding:6px 7px;border-color:#765719;color:#ffd465;font-size:10px;font-weight:750;text-align:center}.pill{display:inline-block;border:1px solid var(--l);border-radius:99px;padding:2px 7px;margin:2px;font-size:10px}.empty{color:var(--m);padding:18px}@media(max-width:900px){.k,.half{grid-column:span 6}.stats{grid-template-columns:repeat(3,1fr)}}@media(max-width:560px){.w{padding:10px}.k,.half{grid-column:1/-1}.stats{grid-template-columns:repeat(2,1fr)}.brand{margin-bottom:10px}}</style></head>
<body><main class="w"><div class="brand"><img src="/assets/blackdaemonfx_logo.jpeg" alt="Logo BlackDaemonFX"><div><strong>BLACKDAEMON<span>FX</span></strong><div class="muted">ESTRATEGIA · DISCIPLINA · RESULTADOS</div></div></div><div class="top"><div><h1>Cuenta activa</h1><div class="muted">Métricas reconstruidas desde SQLite/SQLAlchemy. La rentabilidad se calcula por setup completo, no por piernas TP individuales.</div></div><div class="nav"><a class="btn" href="/">Dashboard</a><a class="btn" href="/instruments">Instrumentos</a></div></div><section class="grid">
<div class="c k"><div class="lab">Balance</div><div class="val" id="balance">—</div></div><div class="c k"><div class="lab">Equity</div><div class="val" id="equity">—</div></div><div class="c k"><div class="lab">Margen libre</div><div class="val" id="free">—</div></div><div class="c k"><div class="lab">Profit flotante</div><div class="val" id="profit">—</div></div>
<div class="c half"><div class="lab">Actividad</div><div class="stats"><div class="s">Trades<b id="total">0</b></div><div class="s">Abiertos<b id="open">0</b></div><div class="s">Cerrados<b id="closed">0</b></div><div class="s">WR piernas<b id="wr">0%</b></div><div class="s">WR setups<b id="swr">0%</b></div><div class="s">PnL neto<b id="pnl">0</b></div></div><div id="stamp" class="muted" style="margin-top:10px">Sin snapshot.</div><div id="dbsource" class="muted" style="margin-top:5px;font-size:11px">Fuente: SQLAlchemy local</div><div id="dbpath" class="muted" style="margin-top:3px;font-size:11px;word-break:break-all">SQLite: verificando ruta…</div><div id="statswindow" class="muted" style="margin-top:3px;font-size:11px">Ventana estadística: historial completo</div></div>
<div class="c half"><div class="lab">Cierres</div><div class="bar" id="bar"></div><div class="leg"><span>TP1 <b id="tp1">0</b></span><span>TP2 <b id="tp2">0</b></span><span>TP histórico <b id="tph">0</b></span><span>Stop Loss <b id="sl">0</b></span><span>BE/Otro <b id="be">0</b></span><span>Emergencia <b id="em">0</b></span></div></div>
<div class="c full"><div class="lab">Ranking de estrategias</div><div class="muted" style="font-size:12px;margin-top:5px">Ordenado por PnL neto de setups cerrados. El factor de beneficio se muestra sólo cuando hay pérdidas registradas.</div><div id="strategyStats" class="ranking"></div></div>
<div class="c full"><div class="historyHead"><div><div class="lab">Historial de operaciones</div><div class="muted" style="font-size:12px;margin-top:4px">Cada auditoría muestra su resumen directamente; abre la vista completa para revisar toda la evidencia técnica.</div></div></div><div class="tbl"><table><thead><tr><th>ID</th><th>Estrategia / instrumento</th><th>Operación</th><th>Entrada</th><th>Resultado</th><th>Cierre</th><th>Auditoría</th></tr></thead><tbody id="rows"></tbody></table></div></div></section></main>
<script>const $=x=>document.getElementById(x),money=v=>v==null?'—':Number(v).toLocaleString('es-CL',{minimumFractionDigits:2,maximumFractionDigits:2}),num=(v,d=2)=>v==null?'—':Number(v).toFixed(d),e=v=>String(v??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function auditHtml(q){const passed=q.passed_confirmations||[],missing=q.missing_confirmations||[],critical=q.critical_confirmation_failures||[],total=q.entry_vs_now_snapshot_count||0,id=q.source_trade_id||q.id,score=q.confirmation_score==null?'—':num(q.confirmation_score,0);let pattern=q.chart_pattern_confirmed?'<div class="auditPattern">Patrón confirmado · <b>'+e(String(q.chart_pattern_name||'confirmado').replaceAll('_',' '))+'</b></div>':'';let link=id?'<a class="btn auditOpen" target="_blank" rel="noopener" href="/account/trade/'+e(id)+'/audit">Ver auditoría completa ↗</a>':'';return '<div class="auditCard"><div class="auditDecision">'+e(q.confirmation_decision||'Sin auditoría persistida')+'</div><div class="auditMeta"><span class="auditStat">Score <b>'+score+'</b></span><span class="auditStat">Snapshots <b>'+e(total)+'</b></span><span class="auditStat good">Aprobadas <b>'+e(passed.length)+'</b></span><span class="auditStat warn">Faltantes <b>'+e(missing.length)+'</b></span><span class="auditStat bad">Críticas <b>'+e(critical.length)+'</b></span></div>'+pattern+link+'</div>'}
function strategyHtml(q,index){const pnl=Number(q.net_pnl||0),pf=q.profit_factor==null?'—':num(q.profit_factor,2),cls=pnl>0?'good':pnl<0?'bad':'';return '<article class="strategy"><div class="strategyHead"><span>#'+(index+1)+' · '+e(q.strategy)+'</span><span class="profit '+cls+'">'+money(pnl)+'</span></div><div class="strategyMeta"><span>'+e(q.setups||0)+' setups</span><span>WR '+num(q.win_rate,1)+'%</span><span>PF '+pf+'</span><span>Prom. '+money(q.average_pnl)+'</span></div></article>'}
function render(a){a=a||{};let x=a.snapshot||{},z=a.stats||{},r=a.recent_trades||[];$('balance').textContent=money(x.balance);$('equity').textContent=money(x.equity);$('free').textContent=money(x.free_margin);$('profit').textContent=money(x.profit);$('profit').className='val '+(Number(x.profit||0)>0?'good':Number(x.profit||0)<0?'bad':'');$('total').textContent=z.total||0;$('open').textContent=z.open||0;$('closed').textContent=z.closed||0;$('wr').textContent=num(z.win_rate,1)+'%';$('swr').textContent=num(z.setup_win_rate,1)+'%';$('pnl').textContent=money(z.net_pnl);$('pnl').className=Number(z.net_pnl||0)>0?'good':Number(z.net_pnl||0)<0?'bad':'';$('strategyStats').innerHTML=(z.by_strategy||[]).map(strategyHtml).join('')||'<div class="empty">Aún no hay setups cerrados para comparar.</div>';$('stamp').textContent=x.snapshot_time?'Último snapshot DB: '+new Date(x.snapshot_time).toLocaleString('es-CL')+' · '+e(x.broker||'MT5'):'Todavía no hay snapshot guardado en la base de datos.';$('dbsource').textContent='Fuente: '+e(a.data_source||'SQLALCHEMY_LOCAL_ONLY')+(a.generated_at?' · leído '+new Date(a.generated_at).toLocaleTimeString('es-CL'):'');let db=a.database||{};$('dbpath').textContent='SQLite: '+e(db.path||'ruta no informada')+' · trades '+e(db.trade_rows??'—')+' · journal '+e(db.trade_journal_rows??'—')+' · snapshots '+e(db.account_snapshot_rows??'—')+(db.bootstrap&&db.bootstrap.recovered?' · RECUPERADA DESDE '+e(db.bootstrap.recovered_from):'');$('statswindow').textContent=a.stats_reset&&a.stats_reset.reset_time?'Estadísticas desde: '+new Date(a.stats_reset.reset_time).toLocaleString('es-CL'):'Ventana estadística: historial completo';[['tp1',z.tp1],['tp2',z.tp2],['tph',z.take_profit],['sl',z.stop_loss],['be',z.break_even],['em',z.emergency]].forEach(([id,v])=>$(id).textContent=v||0);let c=[['#31c48d',z.tp1||0],['#53a7ff',z.tp2||0],['#80d8a8',z.take_profit||0],['#ef6a6a',z.stop_loss||0],['#f5b942',z.break_even||0]],t=Math.max(1,c.reduce((n,q)=>n+q[1],0));$('bar').innerHTML=c.map(q=>q[1]?'<i style="display:block;background:'+q[0]+';width:'+(q[1]/t*100)+'%"></i>':'').join('');$('rows').innerHTML=r.map(q=>'<tr><td>'+e(q.id)+'</td><td><b>'+e(q.strategy)+'</b><div class="tradeMeta">'+e(q.instrument)+'</div></td><td>'+e(q.direction)+'<div class="tradeMeta">'+e(q.status)+' · '+e(q.leg||q.execution_mode)+'</div></td><td>'+e(q.entry_time?new Date(q.entry_time).toLocaleString('es-CL'):'—')+'</td><td><b class="'+(Number(q.net_pnl||0)>0?'good':Number(q.net_pnl||0)<0?'bad':'')+'">'+money(q.net_pnl)+'</b><div class="tradeMeta">RR '+num(q.realized_rr)+' / plan '+num(q.planned_rr)+'</div></td><td>'+e(q.classification)+'</td><td>'+auditHtml(q)+'</td></tr>').join('')||'<tr><td colspan="7" class="empty">No hay trades registrados.</td></tr>'}async function go(){try{let r=await fetch('/api/account?x='+Date.now(),{cache:'no-store'});if(!r.ok)throw new Error('HTTP '+r.status+' '+await r.text());render(await r.json())}catch(err){$('stamp').textContent='Sin conexión: '+err.message;$('dbpath').textContent='SQLite/API: '+err.message}}go();setInterval(go,2500)</script></body></html>'''
